// ─── Configuración ────────────────────────────────────────────────────────
// Rellena estos valores, o defínelos como variables de entorno de n8n. Ojo: por
// defecto n8n bloquea $env dentro de los nodos Code
// (N8N_BLOCK_ENV_ACCESS_IN_NODE); si no la desactivas, se usan los de aquí.
//
// IG_USER_ID es el id de tu cuenta de Instagram Business/Creator, no el @usuario:
//   GET /{page-id}?fields=instagram_business_account
const AJUSTES = {
  IG_USER_ID: 'PON_AQUI_TU_IG_USER_ID',
  GRAPH_API_VERSION: 'v25.0',
  GRAPH_API_HOST: 'https://graph.facebook.com',
};

const env = (() => { try { return $env ?? {}; } catch { return {}; } })();
const IG_USER_ID = env.IG_USER_ID || AJUSTES.IG_USER_ID;
const VERSION = env.GRAPH_API_VERSION || AJUSTES.GRAPH_API_VERSION;
const HOST = env.GRAPH_API_HOST || AJUSTES.GRAPH_API_HOST;

if (IG_USER_ID === 'PON_AQUI_TU_IG_USER_ID') {
  throw new Error('Falta IG_USER_ID: rellénalo en el nodo Configuración o define la variable de entorno.');
}

const TOP = Number($input.first().json.query?.top ?? 5);

// ⚠ Métricas por pieza. Cambian entre versiones de la Graph API: si alguna deja
// de existir Meta devuelve error y ese reel se queda sin ese dato.
const MEDIA_METRICS = [
  'views', 'reach', 'likes', 'comments', 'shares', 'saved',
  // Tiempo medio de visionado en ms. Es la única señal de retención que da la
  // API; si tu versión no la sirve, el panel mostrará alcance/vistas.
  'ig_reels_avg_watch_time',
];

return [{ json: {
  igUserId: IG_USER_ID, version: VERSION, host: HOST,
  top: TOP, mediaMetrics: MEDIA_METRICS.join(','),
} }];

// Un item por reel, para que el siguiente nodo pida sus métricas.
const cfg = $('Configuración').first().json;
const res = $('Publicaciones').first().json ?? {};

if (res.error) return [{ json: { error: res.error.message } }];

// Solo los vídeos son reels; el resto no tiene métricas de reproducción.
return (res.data ?? [])
  .filter((m) => m.media_type === 'VIDEO')
  .slice(0, cfg.top)
  .map((m) => ({ json: { ...m, ...cfg } }));

// Empareja cada reel con su respuesta de insights y ordena por reproducciones.
const bases = $('Seleccionar reels').all();
const stats = $('Insights por reel').all();

const num = (n) => (typeof n === 'number' ? n : null);
const fmt = (n) => (n == null ? null : n >= 1e3 ? (n / 1e3).toFixed(1) + 'K' : String(n));

const reels = bases.map((base, i) => {
  const payload = stats[i]?.json ?? {};
  const byName = {};
  for (const row of payload.data ?? []) {
    byName[row.name] = row.values?.[0]?.value ?? row.total_value?.value ?? null;
  }

  const views = num(byName.views);
  const reach = num(byName.reach);
  const watchMs = num(byName.ig_reels_avg_watch_time);

  return {
    id: base.json.id,
    source: 'instagram',
    title: (base.json.caption ?? '').split('\n')[0].slice(0, 80) || 'Sin título',
    image: base.json.thumbnail_url ?? base.json.media_url,
    permalink: base.json.permalink,
    views: fmt(views),
    likes: fmt(num(byName.likes)),
    comments: fmt(num(byName.comments)),
    shares: fmt(num(byName.shares)),
    saves: fmt(num(byName.saved)),
    // La Graph API no expone retención como tal. Se devuelven las dos señales
    // que sí da, cada una con su nombre, para no presentar una como la otra.
    avgWatchSeconds: watchMs == null ? null : Math.round(watchMs / 100) / 10,
    reachPct: views && reach ? Math.round((reach / views) * 100) : null,
    error: payload.error?.message ?? null,
  };
});

reels.sort((a, b) => (parseFloat(b.views) || 0) - (parseFloat(a.views) || 0));

return [{ json: { source: 'instagram', reels } }];
